import { apiFetch } from './client'
import type { PushSubscription, VapidPublicKey } from './types'

export interface PushSubscriptionCreateInput {
  endpoint: string
  p256dh: string
  auth: string
}

export function createPushSubscription(input: PushSubscriptionCreateInput): Promise<PushSubscription> {
  return apiFetch<PushSubscription>('/api/v1/push-subscriptions', {
    method: 'POST',
    body: JSON.stringify(input),
  })
}

export function getPushSubscriptions(): Promise<PushSubscription[]> {
  return apiFetch<PushSubscription[]>('/api/v1/push-subscriptions')
}

export function getVapidPublicKey(): Promise<VapidPublicKey> {
  return apiFetch<VapidPublicKey>('/api/v1/push-subscriptions/vapid-public-key')
}

